    """
    Implements a regular expression matching algorithm supporting
    literal characters, '.', '*' (zero or more of the preceding 
    element), and '+' (one or more of the preceding element) 
    using dynamic programming approach for efficient matching.
    """
    def is_match(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx < len(pattern) and p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '*':
            return is_match(p_idx + 2, t_idx) or (t_idx < len(text) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.') and is_match(p_idx, t_idx + 1))
        if p_idx < len(pattern) and p_idx + 1 < len(pattern) and pattern[p_idx + 1] == '+':
            return (t_idx < len(text) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.') and is_match(p_idx, t_idx + 1)) or (t_idx + 1 < len(text) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.') and is_match(p_idx + 2, t_idx + 1))
        if p_idx < len(pattern) and t_idx < len(text) and (pattern[p_idx] == text[t_idx] or pattern[p_idx] == '.'):
            return is_match(p_idx + 1, t_idx + 1)
